import json
data = {
  "itbi": {
    "devido": False,
    "base": 420000,
    "fundamento": "CF art. 156, par. 2, I: imunidade na integralizacao de bens em realizacao de capital. Imovel transferido pelo valor da declaracao de IR (420.000), com quotas de igual valor -> nenhum excedente fora da imunidade (STF RE 796.376, Tema 796). Locacao dos 40% (cenarios 60-240 mil/ano) ficaria entre 4,8% e 16,7% da receita operacional projetada (1,2 mi), abaixo do limiar de 50% do CTN art. 37 (atividade preponderante) -> nao afasta a imunidade; monitorar os 3 anos seguintes (empresa nova). Se o imovel fosse integralizado por 900.000 contra capital de 420.000, o excedente de 480.000 escaparia da imunidade (Tema 796). Atencao: a locacao pela propria sociedade e impeditiva do Simples (LC 123 art. 17 XV) mesmo sem preponderancia. (library/cf156_ctn37_itbi.md; library/lc123_vedacoes.md)"
  },
  "integralizacao_imovel": {
    "valor_recomendado": 420000,
    "ganho_capital_pf": 0
  },
  "pro_labore_minimo_recomendado_mensal": {
    "Marina": 0,
    "Felipe": 10000,
    "Luana": 8000
  },
  "distribuicao_mensal_pretendida": 50000,
  "irrf_dividendos_2026_estimado_mensal": 0,
  "simples_possivel": False
}
with open("/work/workspace/deliverable/numeros.json", "w", encoding="utf-8") as f:
    json.dump(data, f, ensure_ascii=False, indent=2)
print(open("/work/workspace/deliverable/numeros.json", encoding="utf-8").read())
EOF

